import { pages, site } from "@/data/content";
import { getPosts } from "@/lib/content";
import { siteUrl } from "@/lib/seo";

/* Prerendered with the rest of the site rather than generated by a script
   and committed, so the feed can never drift from the markdown. */
export const dynamic = "force-static";

const TITLE = `${site.fullName} — Writing`;
const DESCRIPTION = pages["/blogs"].description;

const esc = (value: string) =>
  value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

export function GET() {
  const posts = getPosts();

  const items = posts
    .map((post) => {
      const url = `${siteUrl}/blogs/${post.slug}`;
      return `    <item>
      <title>${esc(post.title)}</title>
      <link>${url}</link>
      <guid isPermaLink="true">${url}</guid>
      <pubDate>${new Date(post.date).toUTCString()}</pubDate>
      <description>${esc(post.excerpt)}</description>
${post.tags.map((t) => `      <category>${esc(t)}</category>`).join("\n")}
    </item>`;
    })
    .join("\n");

  const body = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${esc(TITLE)}</title>
    <link>${siteUrl}/blogs</link>
    <description>${esc(DESCRIPTION)}</description>
    <language>en</language>
    <lastBuildDate>${new Date(posts[0]?.date ?? Date.now()).toUTCString()}</lastBuildDate>
    <atom:link href="${siteUrl}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>
`;

  return new Response(body, {
    headers: { "Content-Type": "application/rss+xml; charset=utf-8" },
  });
}
